     1	// 星雾漂流主循环与输入。
     2	// 注:输入映射当前同时支持 方向键 与 WASD(任务 01 顺手加的),
     3	// 与 docs/DESIGN_NOTES.md 已采纳的「仅键盘方向键、不支持 WASD」要求不一致,尚待开发者裁决。
     4	const canvas = document.getElementById("game");
     5	const ctx = canvas.getContext("2d");
     6	const player = new Player(320, 400);
     7	const GRAVITY = 0.35;
     8	const ROUND_SECONDS = 90;
     9	
    10	const KEYMAP = {
    11	  ArrowLeft: "left", ArrowRight: "right", ArrowUp: "up", ArrowDown: "down",
    12	  KeyA: "left", KeyD: "right", KeyW: "up", KeyS: "down", // WASD 支持
    13	};
    14	
    15	let held = {};
    16	let elapsed = 0;
    17	
    18	window.addEventListener("keydown", (event) => {
    19	  const action = KEYMAP[event.code];
    20	  if (!action) return;
    21	  event.preventDefault();
    22	  held[action] = true;
    23	  if (action === "up") player.thrust();
    24	});
    25	window.addEventListener("keyup", (event) => {
    26	  const action = KEYMAP[event.code];
    27	  if (action) held[action] = false;
    28	});
    29	
    30	function tick(dt) {
    31	  player.vx = (held.left ? -4 : 0) + (held.right ? 4 : 0);
    32	  player.tick(GRAVITY);
    33	  elapsed += dt;
    34	}
    35	
    36	function draw() {
    37	  ctx.fillStyle = "#06070f";
    38	  ctx.fillRect(0, 0, canvas.width, canvas.height);
    39	  ctx.fillStyle = "#e8e2ff";
    40	  ctx.font = "14px sans-serif";
    41	  ctx.fillText(`星尘: ${player.score}`, 12, 24);
    42	  ctx.fillText(`剩余: ${Math.max(0, ROUND_SECONDS - Math.floor(elapsed))}s`, 540, 24);
    43	  ctx.fillStyle = "#9db4ff";
    44	  ctx.fillRect(player.x - 10, player.y - 10, 20, 20);
    45	}
    46	
    47	let last = performance.now();
    48	function frame(now) {
    49	  const dt = Math.min(0.05, (now - last) / 1000);
    50	  last = now;
    51	  tick(dt);
    52	  draw();
    53	  requestAnimationFrame(frame);
    54	}
    55	requestAnimationFrame(frame);
