     1	// 玩家小飞船:移动与推进。
     2	// 注:推进当前按「可二段推进」实现(任务 01 的进行中试验),
     3	// 与 docs/DESIGN_NOTES.md 已采纳的「单次推进」要求不一致,尚待开发者裁决。
     4	const MAX_JUMPS = 2; // 二段推进上限
     5	
     6	class Player {
     7	  constructor(x, y) {
     8	    this.x = x;
     9	    this.y = y;
    10	    this.vx = 0;
    11	    this.vy = 0;
    12	    this.jumpsUsed = 0;
    13	    this.score = 0;
    14	  }
    15	
    16	  thrust() {
    17	    if (this.jumpsUsed >= MAX_JUMPS) {
    18	      return false; // 二段推进次数用尽,需落地重置
    19	    }
    20	    this.jumpsUsed += 1;
    21	    this.vy = -6.5;
    22	    return true;
    23	  }
    24	
    25	  land() {
    26	    this.jumpsUsed = 0; // 落地重置二段推进
    27	  }
    28	
    29	  tick(gravity) {
    30	    this.vy += gravity;
    31	    this.x += this.vx;
    32	    this.y += this.vy;
    33	    if (this.y >= 400) {
    34	      this.y = 400;
    35	      this.vy = 0;
    36	      this.land();
    37	    }
    38	  }
    39	}
